export const defaultParameters = [
  'blobVersionedHashes',
  'chainId',
  'fees',
  'gas',
  'nonce',
  'type',
] as const

/** @internal */
export const supportsFillTransaction = /*#__PURE__*/ new LruMap<boolean>(128)

export type PrepareTransactionRequestParameterType =
  | 'blobVersionedHashes'
  | 'chainId'
  | 'fees'
  | 'gas'
  | 'nonce'
  | 'sidecars'
  | 'type'
type ParameterTypeToParameters<
  parameterType extends PrepareTransactionRequestParameterType,
> = parameterType extends 'fees'
  ? 'maxFeePerGas' | 'maxPriorityFeePerGas' | 'gasPrice'
  : parameterType

export type PrepareTransactionRequestRequest<
  chain extends Chain | undefined = Chain | undefined,
  chainOverride extends Chain | undefined = Chain | undefined,
  ///
  _derivedChain extends Chain | undefined = DeriveChain<chain, chainOverride>,
> = UnionOmit<FormattedTransactionRequest<_derivedChain>, 'from'> &
  GetTransactionRequestKzgParameter & {
    /**
     * Nonce manager to use for the transaction request.
     */
    nonceManager?: NonceManager | undefined
    /**
     * Parameters to prepare for the transaction request.
     *
     * @default ['blobVersionedHashes', 'chainId', 'fees', 'gas', 'nonce', 'type']
     */
    parameters?: readonly PrepareTransactionRequestParameterType[] | undefined
  }

export type PrepareTransactionRequestParameters<
  chain extends Chain | undefined = Chain | undefined,
  account extends Account | undefined = Account | undefined,
  chainOverride extends Chain | undefined = Chain | undefined,
  accountOverride extends Account | Address | undefined =
    | Account
    | Address
    | undefined,
  request extends PrepareTransactionRequestRequest<
    chain,
    chainOverride
  > = PrepareTransactionRequestRequest<chain, chainOverride>,
> = request &
  GetAccountParameter<account, accountOverride, false, true> &
  GetChainParameter<chain, chainOverride> &
  GetTransactionRequestKzgParameter<request> & { chainId?: number | undefined }

/**
 * Infers a chain-specific (non-built-in) transaction type from the request
 * shape. Returns the custom `type` (e.g. `'tempo'`) only when the request
 * uniquely matches a custom member of the chain's formatted request union (i.e.
 * it does not also match any built-in member). Built-in chains have no custom
 * members, so this resolves to `never` and leaves their inference unchanged.
 */
type ExtractCustomFormattedTransactionType<
  chain extends Chain | undefined,
  request,
  ///
  _candidates = UnionOmit<FormattedTransactionRequest<chain>, 'from'>,
  _matched extends string = _candidates extends object
    ? request extends ExactPartial<_candidates>
      ? _candidates extends { type?: infer type | undefined }
        ? Extract<type, string>
        : never
      : never
    : never,
  _builtin = NonNullable<TransactionRequest['type']>,
> = IsNever<Extract<_matched, _builtin>> extends true
  ? Exclude<_matched, _builtin>
  : never

export type PrepareTransactionRequestReturnType<
  chain extends Chain | undefined = Chain | undefined,
  account extends Account | undefined = Account | undefined,
  chainOverride extends Chain | undefined = Chain | undefined,
  accountOverride extends Account | Address | undefined =
    | Account
    | Address
    | undefined,
  request extends PrepareTransactionRequestRequest<
    chain,
    chainOverride
  > = PrepareTransactionRequestRequest<chain, chainOverride>,
  ///
  _derivedAccount extends Account | Address | undefined = DeriveAccount<
    account,
    accountOverride
  >,
  _derivedChain extends Chain | undefined = DeriveChain<chain, chainOverride>,
  _customTransactionType extends string = ExtractCustomFormattedTransactionType<
    _derivedChain,
    request
  >,
  _transactionType = request['type'] extends string
    ? request['type']
    : IsNever<_customTransactionType> extends false
      ? _customTransactionType
      : request['type'] extends string | undefined
        ? request['type']
        : GetTransactionType<request> extends 'legacy'
          ? unknown
          : GetTransactionType<request>,
  _transactionRequest = ExtractFormattedTransactionRequest<
    _derivedChain,
    { type?: _transactionType extends string ? _transactionType : undefined }
  >,
> = Prettify<
  UnionRequiredBy<
    Extract<
      UnionOmit<FormattedTransactionRequest<_derivedChain>, 'from'> &
        (_derivedChain extends Chain
          ? { chain: _derivedChain }
          : { chain?: undefined }) &
        (_derivedAccount extends Account
          ? { account: _derivedAccount; from: Address }
          : { account?: undefined; from?: undefined }),
      IsNever<_transactionRequest> extends true
        ? unknown
        : ExactPartial<_transactionRequest>
    > & { chainId?: number | undefined },
    ParameterTypeToParameters<
      request['parameters'] extends readonly PrepareTransactionRequestParameterType[]
        ? request['parameters'][number]
        : (typeof defaultParameters)[number]
    >
  > &
    (unknown extends request['kzg'] ? {} : Pick<request, 'kzg'>) & {
      // TODO(v3): Extract `prepareTransactionRequest` response into a named object of `{ capabilities, request }.
      _capabilities?:
        | ExtractCapabilities<'fillTransaction', 'ReturnType'>
        | undefined
    }
>

export type PrepareTransactionRequestErrorType =
  | AccountNotFoundErrorType
  | AssertRequestErrorType
  | ChainMismatchErrorType
  | ParseAccountErrorType
  | GetBlockErrorType
  | GetTransactionCountErrorType
  | EstimateGasErrorType
  | EstimateFeesPerGasErrorType
  | ErrorType

/**
 * Prepares a transaction request for signing.
 *
 * - Docs: https://viem.sh/docs/actions/wallet/prepareTransactionRequest
 *
 * @param args - {@link PrepareTransactionRequestParameters}
 * @returns The transaction request. {@link PrepareTransactionRequestReturnType}
 *
 * @example
 * import { createWalletClient, custom } from 'viem'
 * import { mainnet } from 'viem/chains'
 * import { prepareTransactionRequest } from 'viem/actions'
 *
 * const client = createWalletClient({
 *   chain: mainnet,
 *   transport: custom(window.ethereum),
 * })
 * const request = await prepareTransactionRequest(client, {
 *   account: '0xA0Cf798816D4b9b9866b5330EEa46a18382f251e',
 *   to: '0x0000000000000000000000000000000000000000',
 *   value: 1n,
 * })
 *
 * @example
 * // Account Hoisting
 * import { createWalletClient, http } from 'viem'
 * import { privateKeyToAccount } from 'viem/accounts'
 * import { mainnet } from 'viem/chains'
 * import { prepareTransactionRequest } from 'viem/actions'
 *
 * const client = createWalletClient({
 *   account: privateKeyToAccount('0x…'),
 *   chain: mainnet,
 *   transport: custom(window.ethereum),
 * })
 * const request = await prepareTransactionRequest(client, {
 *   to: '0x0000000000000000000000000000000000000000',
 *   value: 1n,
 * })
 */
export async function prepareTransactionRequest<
  chain extends Chain | undefined,
  account extends Account | undefined,
  const request extends PrepareTransactionRequestRequest<chain, chainOverride>,
  accountOverride extends Account | Address | undefined = undefined,
  chainOverride extends Chain | undefined = undefined,
>(
  client: Client<Transport, chain, account>,
  args: PrepareTransactionRequestParameters<
    chain,
    account,
    chainOverride,
    accountOverride,
    request
  >,
): Promise<
  PrepareTransactionRequestReturnType<
    chain,
    account,
    chainOverride,
    accountOverride,
    request
  >
> {
  let request = { ...args } as PrepareTransactionRequestParameters

  if (typeof request.account === 'undefined') request.account = client.account
  request.parameters ??= defaultParameters

  const {
    account: account_,
    chain = client.chain,
    nonceManager,
    parameters,
  } = request

  const prepareTransactionRequest = (() => {
    if (typeof chain?.prepareTransactionRequest === 'function')
      return {
        fn: chain.prepareTransactionRequest,
        runAt: ['beforeFillTransaction'],
      }
    if (Array.isArray(chain?.prepareTransactionRequest))
      return {
        fn: chain.prepareTransactionRequest[0],
        runAt: chain.prepareTransactionRequest[1].runAt,
      }
    return undefined
  })()

  let chainId: number | undefined
  async function getChainId(): Promise<number> {
    if (chainId) return chainId
    if (typeof request.chainId !== 'undefined') return request.chainId
    if (chain) return chain.id
    const chainId_ = await getAction(client, getChainId_, 'getChainId')({})
    chainId = chainId_
    return chainId
  }

  let account = account_ ? parseAccount(account_) : account_

  let nonce = request.nonce
  if (
    prepareTransactionRequest?.fn &&
    prepareTransactionRequest.runAt?.includes('beforeFillTransaction')
  ) {
    request =
      (await prepareTransactionRequest.fn(
        { ...request, chain },
        {
          client,
          phase: 'beforeFillTransaction',
        },
      )) ?? request
    nonce ??= request.nonce
    const sender = request.account ?? (request as TransactionRequest).from
    account = sender ? parseAccount(sender) : undefined
  }

  // The nonce manager hands out nonces in call order, so the nonce is consumed
  // here, but awaited with the other parameters.
  let consumedNonce: Promise<number> | undefined
  if (
    parameters.includes('nonce') &&
    typeof nonce === 'undefined' &&
    account &&
    nonceManager
  ) {
    const chainId = await getChainId()
    consumedNonce = nonceManager.consume({
      address: account.address,
      chainId,
      client,
    })
    // A rejection is thrown when the nonce is awaited.
    consumedNonce.catch(() => {})
  }

  const attemptFill = (() => {
    // Do not attempt if blobs are provided.
    if (
      (parameters.includes('blobVersionedHashes') ||
        parameters.includes('sidecars')) &&
      request.kzg &&
      request.blobs
    )
      return false

    // Always attempt if the caller explicitly requested a non-empty set of
    // `parameters` and a fee payer signature is being requested (e.g. Tempo
    // sponsorship via `feePayer: true`/`Account`) and has not already been
    // filled. The fee payer signature can only be obtained as a side effect
    // of `eth_fillTransaction` (the relay co-signs the returned transaction),
    // so it must be called even when nonce/gas/fees are already fully
    // populated, or when the caller's `parameters` option omits `'fees'`/
    // `'gas'` entirely — otherwise the transaction silently ends up without
    // a fee payer signature. This check intentionally runs before the
    // `shouldAttempt` gate below, since fee-payer sponsorship is independent
    // of which parameters the caller opted into filling.
    //
    // The `parameters.length > 0` guard excludes internal micro-prepare calls
    // that explicitly pass an empty `parameters` array (e.g. `estimateGas`'s
    // internal `prepareTransactionRequest` call for local accounts) — those
    // are deliberately scoped to fill nothing, and should not independently
    // re-attempt `eth_fillTransaction` for fee-payer sponsorship.
    if (
      parameters.length > 0 &&
      'feePayer' in request &&
      (request as any).feePayer &&
      !('feePayerSignature' in request && (request as any).feePayerSignature)
    )
      return true

    // Sponsorship can route fill requests to a different endpoint, so it must
    // bypass support state cached from a non-sponsored request.
    if (supportsFillTransaction.get(client.uid) === false) return false

    // Should attempt `eth_fillTransaction` if "fees" or "gas" are required to be populated,
    // otherwise, can just use the other individual calls.
    const shouldAttempt = ['fees', 'gas'].some((parameter) =>
      parameters.includes(parameter as PrepareTransactionRequestParameterType),
    )
    if (!shouldAttempt) return false

    // Check if `eth_fillTransaction` needs to be called.
    if (parameters.includes('chainId') && typeof request.chainId !== 'number')
      return true
    if (
      parameters.includes('nonce') &&
      typeof nonce !== 'number' &&
      !consumedNonce
    )
      return true
    if (
      parameters.includes('fees') &&
      typeof request.gasPrice !== 'bigint' &&
      (typeof request.maxFeePerGas !== 'bigint' ||
        typeof (request as any).maxPriorityFeePerGas !== 'bigint')
    )
      return true
    if (parameters.includes('gas') && typeof request.gas !== 'bigint')
      return true
    return false
  })()

  // `eth_fillTransaction` and chain hooks read the nonce from the request.
  if (consumedNonce && (attemptFill || prepareTransactionRequest))
    nonce = await consumedNonce

  let filledChainId: number | undefined
  const fill = (request: PrepareTransactionRequestParameters) =>
    getAction(
      client,
      fillTransaction,
      'fillTransaction',
    )({ ...request, nonce } as FillTransactionParameters).then((result) => {
      const {
        chainId,
        from,
        gas,
        gasPrice,
        nonce,
        maxFeePerBlobGas,
        maxFeePerGas,
        maxPriorityFeePerGas,
        type,
        ...rest
      } = result.transaction
      const feeToken = 'feeToken' in rest ? rest.feeToken : undefined
      const hasFilledFeePayerSignature =
        'feePayerSignature' in rest &&
        rest.feePayerSignature !== null &&
        typeof rest.feePayerSignature !== 'undefined'
      const shouldUseFilledFeeToken =
        typeof feeToken !== 'undefined' &&
        feeToken !== null &&
        (!('feeToken' in request) || hasFilledFeePayerSignature)
      supportsFillTransaction.set(client.uid, true)
      filledChainId = chainId
      // The fee payer signs over the filled fee token, so a requested one must not replace or outlive it.
      type WithFeeToken = { feeToken?: unknown }
      const { feeToken: _feeToken, ...unsponsored } = request as WithFeeToken
      return {
        ...(hasFilledFeePayerSignature ? unsponsored : request),
        ...(from ? { from } : {}),
        ...(type && !request.type ? { type } : {}),
        ...(typeof gas !== 'undefined' ? { gas } : {}),
        ...(typeof gasPrice !== 'undefined' ? { gasPrice } : {}),
        ...(typeof nonce !== 'undefined' ? { nonce } : {}),
        ...(typeof maxFeePerBlobGas !== 'undefined' &&
        request.type !== 'legacy' &&
        request.type !== 'eip2930'
          ? { maxFeePerBlobGas }
          : {}),
        ...(typeof maxFeePerGas !== 'undefined' &&
        request.type !== 'legacy' &&
        request.type !== 'eip2930'
          ? { maxFeePerGas }
          : {}),
        ...(typeof maxPriorityFeePerGas !== 'undefined' &&
        request.type !== 'legacy' &&
        request.type !== 'eip2930'
          ? { maxPriorityFeePerGas }
          : {}),
        ...('nonceKey' in rest && typeof rest.nonceKey !== 'undefined'
          ? { nonceKey: rest.nonceKey }
          : {}),
        // Validity bounds are part of the fee-payer signing payload.
        ...('validBefore' in rest &&
        rest.validBefore !== null &&
        typeof rest.validBefore !== 'undefined'
          ? { validBefore: rest.validBefore }
          : {}),
        ...('validAfter' in rest &&
        rest.validAfter !== null &&
        typeof rest.validAfter !== 'undefined'
          ? { validAfter: rest.validAfter }
          : {}),
        ...('keyAuthorization' in rest &&
        typeof rest.keyAuthorization !== 'undefined' &&
        rest.keyAuthorization !== null &&
        !('keyAuthorization' in request)
          ? { keyAuthorization: rest.keyAuthorization }
          : {}),
        ...('feePayerSignature' in rest &&
        typeof rest.feePayerSignature !== 'undefined' &&
        rest.feePayerSignature !== null
          ? { feePayerSignature: rest.feePayerSignature }
          : {}),
        ...(shouldUseFilledFeeToken ? { feeToken } : {}),
        ...(result.capabilities ? { _capabilities: result.capabilities } : {}),
      }
    })

  const recover = (
    e: unknown,
    request: PrepareTransactionRequestParameters,
  ) => {
    const error = e as FillTransactionErrorType

    if (error.name !== 'TransactionExecutionError') return request

    const nonceMismatch = error.walk?.(
      (error) => error instanceof FeePayerNonceMismatchError,
    )
    if (nonceMismatch) throw e

    const executionReverted = error.walk?.((e) => {
      const error = e as BaseError
      return error.name === 'ExecutionRevertedError'
    })
    if (executionReverted) throw e

    const unsupported = error.walk?.((e) => {
      const error = e as BaseError
      return (
        error.name === 'MethodNotFoundRpcError' ||
        error.name === 'MethodNotSupportedRpcError' ||
        error.message?.includes('eth_fillTransaction is not available')
      )
    })
    if (unsupported) supportsFillTransaction.set(client.uid, false)

    return request
  }

  const fillResult = attemptFill
    ? await fill(request).catch(async (error) => {
        const retry =
          prepareTransactionRequest?.fn &&
          prepareTransactionRequest.runAt?.includes('afterFillTransactionError')
            ? await prepareTransactionRequest.fn(
                { ...request, chain },
                { client, error, phase: 'afterFillTransactionError' },
              )
            : undefined
        if (!retry) return recover(error, request)
        return fill(retry).catch((error) => recover(error, retry))
      })
    : request

  nonce ??= fillResult.nonce

  request = {
    ...(fillResult as any),
    ...(account ? { from: account?.address } : {}),
    ...(typeof nonce !== 'undefined' ? { nonce } : {}),
  }

  // The filled chain id only applies when neither the request nor the chain provides one.
  if (typeof filledChainId !== 'undefined') {
    request.chainId ??= chain?.id ?? filledChainId
    if (request.chainId !== filledChainId)
      throw new ChainMismatchError({
        chain:
          chain?.id === request.chainId
            ? chain
            : ({ id: request.chainId, name: 'Unknown' } as Chain),
        currentChainId: filledChainId,
      })
  }

  const { blobs, gas, kzg, type } = request

  if (
    prepareTransactionRequest?.fn &&
    prepareTransactionRequest.runAt?.includes('beforeFillParameters')
  ) {
    request =
      (await prepareTransactionRequest.fn(
        { ...request, chain },
        {
          client,
          phase: 'beforeFillParameters',
        },
      )) ?? request
  }

  let block: Promise<Block> | undefined
  function getBlock(): Promise<Block> {
    block ??= getAction(client, getBlock_, 'getBlock')({ blockTag: 'latest' })
    return block
  }

  // Chain fee hooks receive the block and the request, so the requests they
  // depend on are made in sequence.
  const hasFeeHooks = Object.values(chain?.fees ?? {}).some(
    (fee) => typeof fee === 'function',
  )

  // The nonce does not depend on the type or the fees, so it is fetched
  // concurrently with them.
  const noncePromise =
    typeof nonce === 'undefined' && consumedNonce
      ? consumedNonce
      : parameters.includes('nonce') &&
          typeof nonce === 'undefined' &&
          account &&
          !nonceManager
        ? getAction(
            client,
            getTransactionCount,
            'getTransactionCount',
          )({
            address: account.address,
            blockTag: 'pending',
          })
        : undefined
  // A rejection is thrown when the nonce is awaited.
  noncePromise?.catch(() => {})
  if (noncePromise && hasFeeHooks) request.nonce = await noncePromise

  try {
    if (
      (parameters.includes('blobVersionedHashes') ||
        parameters.includes('sidecars')) &&
      blobs &&
      kzg
    ) {
      const commitments = blobsToCommitments({ blobs, kzg })

      if (parameters.includes('blobVersionedHashes')) {
        const versionedHashes = commitmentsToVersionedHashes({
          commitments,
          to: 'hex',
        })
        request.blobVersionedHashes = versionedHashes
      }
      if (parameters.includes('sidecars')) {
        const proofs = blobsToProofs({ blobs, commitments, kzg })
        const sidecars = toBlobSidecars({
          blobs,
          commitments,
          proofs,
          to: 'hex',
        })
        request.sidecars = sidecars
      }
    }

    if (parameters.includes('chainId')) request.chainId = await getChainId()

    let priorityFeePromise: Promise<bigint> | undefined

    if (
      (parameters.includes('fees') || parameters.includes('type')) &&
      typeof type === 'undefined'
    ) {
      try {
        request.type = getTransactionType(
          request as TransactionSerializable,
        ) as any
      } catch {
        let isEip1559Network = eip1559NetworkCache.get(client.uid)
        if (typeof isEip1559Network === 'undefined') {
          // EIP-1559 fees will most likely be needed, so without chain fee
          // hooks the priority fee is estimated concurrently with the block
          // that decides the type. On legacy networks, it goes unused.
          if (parameters.includes('fees') && !hasFeeHooks) {
            priorityFeePromise = internal_estimateMaxPriorityFeePerGas(client, {
              block: getBlock(),
              chain,
              request: request as PrepareTransactionRequestParameters,
            })
            // A rejection is thrown when the priority fee is awaited.
            priorityFeePromise.catch(() => {})
          }
          const block = await getBlock()
          isEip1559Network = typeof block?.baseFeePerGas === 'bigint'
          eip1559NetworkCache.set(client.uid, isEip1559Network)
        }
        request.type = isEip1559Network ? 'eip1559' : 'legacy'
      }
    }

    if (parameters.includes('fees')) {
      // TODO(4844): derive blob base fees once https://github.com/ethereum/execution-apis/pull/486 is merged.

      if (request.type !== 'legacy' && request.type !== 'eip2930') {
        // EIP-1559 fees
        if (
          typeof request.maxFeePerGas === 'undefined' ||
          typeof request.maxPriorityFeePerGas === 'undefined'
        ) {
          // Without chain fee hooks, the priority fee does not depend on the
          // block, so it is estimated concurrently with the block request.
          const [block, priorityFee] = await Promise.all([
            getBlock(),
            hasFeeHooks || typeof request.maxPriorityFeePerGas === 'bigint'
              ? undefined
              : (priorityFeePromise ??
                internal_estimateMaxPriorityFeePerGas(client, {
                  block: getBlock(),
                  chain,
                  request: request as PrepareTransactionRequestParameters,
                })),
          ])
          const { maxFeePerGas, maxPriorityFeePerGas } =
            await internal_estimateFeesPerGas(client, {
              block,
              chain,
              request: (typeof priorityFee === 'bigint'
                ? { ...request, maxPriorityFeePerGas: priorityFee }
                : request) as PrepareTransactionRequestParameters,
            })

          if (
            typeof request.maxPriorityFeePerGas === 'undefined' &&
            typeof request.maxFeePerGas === 'bigint' &&
            request.maxFeePerGas < maxPriorityFeePerGas
          )
            throw new MaxFeePerGasTooLowError({
              maxPriorityFeePerGas,
            })

          request.maxPriorityFeePerGas = maxPriorityFeePerGas
          request.maxFeePerGas = maxFeePerGas
        }
      } else {
        // Legacy fees
        if (
          typeof request.maxFeePerGas !== 'undefined' ||
          typeof request.maxPriorityFeePerGas !== 'undefined'
        )
          throw new Eip1559FeesNotSupportedError()

        if (typeof request.gasPrice === 'undefined') {
          const { gasPrice: gasPrice_ } = await internal_estimateFeesPerGas(
            client,
            {
              // Only chain fee hooks read the block for legacy fees.
              block: hasFeeHooks ? await getBlock() : undefined,
              chain,
              request: request as PrepareTransactionRequestParameters,
              type: 'legacy',
            },
          )
          request.gasPrice = gasPrice_
        }
      }
    }
  } catch (error) {
    // A failed nonce request takes precedence over errors from the other
    // parameters.
    await noncePromise
    throw error
  }

  if (noncePromise) request.nonce = await noncePromise

  if (parameters.includes('gas') && typeof gas === 'undefined')
    request.gas = await getAction(
      client,
      estimateGas,
      'estimateGas',
    )({
      ...request,
      account,
      prepare: account?.type === 'local' ? [] : ['blobVersionedHashes'],
    } as EstimateGasParameters)

  if (
    prepareTransactionRequest?.fn &&
    prepareTransactionRequest.runAt?.includes('afterFillParameters')
  )
    request =
      (await prepareTransactionRequest.fn(
        { ...request, chain },
        {
          client,
          phase: 'afterFillParameters',
        },
      )) ?? request

  assertRequest(request as AssertRequestParameters)

  delete request.parameters

  return request as any
}
