export type BlockParameters = OneOf<
  | {
      /** The block number to check if the contract was already deployed. */
      blockNumber?: bigint | undefined
    }
  | {
      /**
       * The block tag to check if the contract was already deployed.
       * Pre-delegated ERC-8010 signatures are verified against `'pending'` when no block is selected.
       * @default 'latest'
       */
      blockTag?: BlockTag | undefined
    }
  | {
      /** The block hash to check if the contract was already deployed. Implements [EIP-1898](https://eips.ethereum.org/EIPS/eip-1898). */
      blockHash: Hash
      /** Whether or not to require the block to be in the canonical chain. Only allowed in conjunction with `blockHash`. */
      requireCanonical?: boolean | undefined
    }
>

export type VerifyHashParameters = BlockParameters & {
  /** The address that signed the original message. */
  address: Address
  /** The chain to use. */
  chain?: Chain | null | undefined
  /** The address of the ERC-6492 signature verifier contract. */
  erc6492VerifierAddress?: Address | undefined
  /** The hash to be verified. */
  hash: Hex
  /** Multicall3 address for ERC-8010 verification. */
  multicallAddress?: Address | undefined
  /** The signature that was generated by signing the message with the address's private key. */
  signature: Hex | ByteArray | Signature
  /** @deprecated use `erc6492VerifierAddress` instead. */
  universalSignatureVerifierAddress?: Address | undefined
  /** Chooses which verification path to try first before falling back. */
  mode?: 'auto' | 'eoa' | (string & {}) | undefined
} & OneOf<{ factory: Address; factoryData: Hex } | {}>

export type VerifyHashReturnType = boolean

export type VerifyHashErrorType =
  | BytesToHexErrorType
  | CallErrorType
  | ConcatHexErrorType
  | EncodeDeployDataErrorType
  | EncodeFunctionDataErrorType
  | ErrorType
  | GetAddressErrorType
  | GetCodeErrorType
  | InvalidHexBooleanError
  | IsAddressEqualErrorType
  | IsHexErrorType
  | NumberToHexErrorType
  | ReadContractErrorType
  | RecoverAddressErrorType
  | SerializeSignatureErrorType

/**
 * Verifies a message hash onchain using ERC-6492.
 *
 * @param client - Client to use.
 * @param parameters - {@link VerifyHashParameters}
 * @returns Whether or not the signature is valid. {@link VerifyHashReturnType}
 */
export async function verifyHash<chain extends Chain | undefined>(
  client: Client<Transport, chain>,
  parameters: VerifyHashParameters,
): Promise<VerifyHashReturnType> {
  const {
    address,
    chain = client.chain,
    hash,
    erc6492VerifierAddress:
      verifierAddress = parameters.universalSignatureVerifierAddress ??
      (() => {
        const { blockNumber } = parameters
        const verifier = chain?.contracts?.erc6492Verifier
        // Use the deployless validator for blocks before the verifier was created.
        if (
          blockNumber !== undefined &&
          verifier?.blockCreated &&
          verifier.blockCreated > blockNumber
        )
          return undefined
        return verifier?.address
      })(),
    multicallAddress = parameters.multicallAddress ??
      chain?.contracts?.multicall3?.address,
    mode = 'auto',
  } = parameters

  // No signature is valid for the zero address.
  if (address === zeroAddress) return false

  if (chain?.verifyHash) return await chain.verifyHash(client, parameters)

  const signature = (() => {
    const signature = parameters.signature
    if (isHex(signature)) return signature
    if (typeof signature === 'object' && 'r' in signature && 's' in signature)
      return serializeSignature(signature)
    return bytesToHex(signature)
  })()
  try {
    if (mode === 'eoa') {
      try {
        const verified = isAddressEqual(
          getAddress(address),
          await recoverAddress({ hash, signature }),
        )
        if (verified) return true
      } catch {}
    }

    if (SignatureErc8010.validate(signature))
      return await verifyErc8010(client, {
        ...parameters,
        multicallAddress,
        signature,
      })
    return await verifyErc6492(client, {
      ...parameters,
      verifierAddress,
      signature,
    })
  } catch (error) {
    if (mode !== 'eoa') {
      // Fallback attempt to verify the signature via ECDSA recovery.
      try {
        const verified = isAddressEqual(
          getAddress(address),
          await recoverAddress({ hash, signature }),
        )
        if (verified) return true
      } catch {}
    }

    if (error instanceof VerificationError) {
      // if the execution fails, the signature was not valid and an internal method inside of the validator reverted
      // this can happen for many reasons, for example if signer can not be recovered from the signature
      // or if the signature has no valid format
      return false
    }

    throw error
  }
}

/** @internal */
export async function verifyErc8010(
  client: Client,
  parameters: verifyErc8010.Parameters,
) {
  const {
    address,
    blockHash,
    blockNumber,
    blockTag,
    hash,
    multicallAddress,
    requireCanonical,
  } = parameters

  const {
    authorization: authorization_ox,
    data: initData,
    signature,
    to,
  } = SignatureErc8010.unwrap(parameters.signature)

  // Check if already delegated
  const code = await getCode(client, {
    address,
    blockHash,
    blockNumber,
    blockTag,
    requireCanonical,
  } as never)

  // If already delegated, perform standard ERC-1271 verification.
  if (code === concatHex(['0xef0100', authorization_ox.address]))
    return await verifyErc1271(client, {
      ...parameters,
      signature,
    })

  const authorization = {
    address: authorization_ox.address,
    chainId: Number(authorization_ox.chainId),
    nonce: Number(authorization_ox.nonce),
    r: numberToHex(authorization_ox.r, { size: 32 }),
    s: numberToHex(authorization_ox.s, { size: 32 }),
    yParity: authorization_ox.yParity,
  } as const

  const valid = await verifyAuthorization({
    address,
    authorization,
  })
  if (!valid) throw new VerificationError()

  // Deployless verification.
  const { data: aggregate3Data } = await call({ ...client, ccipRead: false }, {
    ...(multicallAddress
      ? { to: multicallAddress }
      : { code: multicall3Bytecode }),
    authorizationList: [authorization],
    blockHash,
    blockNumber,
    blockTag: blockTag ?? 'pending',
    data: encodeFunctionData({
      abi: multicall3Abi,
      functionName: 'aggregate3',
      args: [
        [
          ...(initData
            ? ([
                {
                  allowFailure: true,
                  target: to ?? address,
                  callData: initData,
                },
              ] as const)
            : []),
          {
            allowFailure: true,
            target: address,
            callData: encodeFunctionData({
              abi: erc1271Abi,
              functionName: 'isValidSignature',
              args: [hash, signature],
            }),
          },
        ],
      ],
    }),
    requireCanonical,
  } as CallParameters)
  const results = decodeFunctionResult({
    abi: multicall3Abi,
    functionName: 'aggregate3',
    data: aggregate3Data ?? '0x',
  })

  const result = results[results.length - 1]

  if (result?.success && result.returnData.startsWith('0x1626ba7e')) return true
  throw new VerificationError()
}

export namespace verifyErc8010 {
  export type Parameters = BlockParameters & {
    /** The address that signed the original message. */
    address: Address
    /** The hash to be verified. */
    hash: Hex
    /** Multicall3 address for ERC-8010 verification. */
    multicallAddress?: Address | undefined
    /** The signature that was generated by signing the message with the address's private key. */
    signature: Hex
  }
}

/** @internal */
// biome-ignore lint/correctness/noUnusedVariables: _
async function verifyErc6492(
  client: Client,
  parameters: verifyErc6492.Parameters,
) {
  const {
    address,
    factory,
    factoryData,
    hash,
    signature,
    verifierAddress,
    ...rest
  } = parameters

  const wrappedSignature = await (async () => {
    // If no `factory` or `factoryData` is provided, it is assumed that the
    // address is not a Smart Account, or the Smart Account is already deployed.
    if (!factory && !factoryData) return signature

    // If the signature is already wrapped, return the signature.
    if (SignatureErc6492.validate(signature)) return signature

    // If the Smart Account is not deployed, wrap the signature with a 6492 wrapper
    // to perform counterfactual validation.
    return SignatureErc6492.wrap({
      data: factoryData!,
      signature,
      to: factory!,
    })
  })()

  const args = verifierAddress
    ? ({
        batch: false,
        to: verifierAddress,
        data: encodeFunctionData({
          abi: erc6492SignatureValidatorAbi,
          functionName: 'isValidSig',
          args: [address, hash, wrappedSignature],
        }),
        ...rest,
      } as unknown as CallParameters)
    : ({
        data: encodeDeployData({
          abi: erc6492SignatureValidatorAbi,
          args: [address, hash, wrappedSignature],
          bytecode: erc6492SignatureValidatorByteCode,
        }),
        ...rest,
      } as unknown as CallParameters)

  // Verification calls run without CCIP-Read. They use `call` directly
  // because a client's own `call` action keeps its CCIP-Read setting.
  const { data } = await call({ ...client, ccipRead: false }, args).catch(
    (error) => {
      if (error instanceof CallExecutionError) throw new VerificationError()
      throw error
    },
  )

  if (hexToBool(data ?? '0x0')) return true
  throw new VerificationError()
}

export namespace verifyErc6492 {
  export type Parameters = BlockParameters & {
    /** The address that signed the original message. */
    address: Address
    /** The hash to be verified. */
    hash: Hex
    /** The signature that was generated by signing the message with the address's private key. */
    signature: Hex
    /** The address of the ERC-6492 signature verifier contract. */
    verifierAddress?: Address | undefined
  } & OneOf<{ factory: Address; factoryData: Hex } | {}>
}

/** @internal */
export async function verifyErc1271(
  client: Client,
  parameters: verifyErc1271.Parameters,
) {
  const {
    address,
    blockHash,
    blockNumber,
    blockTag,
    hash,
    requireCanonical,
    signature,
  } = parameters

  const { data } = await call({ ...client, ccipRead: false }, {
    batch: false,
    blockHash,
    blockNumber,
    blockTag,
    data: encodeFunctionData({
      abi: erc1271Abi,
      functionName: 'isValidSignature',
      args: [hash, signature],
    }),
    requireCanonical,
    to: address,
  } as CallParameters).catch((error) => {
    if (error instanceof CallExecutionError) throw new VerificationError()
    throw error
  })

  const result = (() => {
    try {
      return decodeFunctionResult({
        abi: erc1271Abi,
        functionName: 'isValidSignature',
        data: data ?? '0x',
      })
    } catch {
      throw new VerificationError()
    }
  })()

  if (result.startsWith('0x1626ba7e')) return true
  throw new VerificationError()
}

export namespace verifyErc1271 {
  export type Parameters = BlockParameters & {
    /** The address that signed the original message. */
    address: Address
    /** The hash to be verified. */
    hash: Hex
    /** The signature that was generated by signing the message with the address's private key. */
    signature: Hex
  }
}

class VerificationError extends Error {}
